	this.frame_11 = function() {
		this.stop();
		
		var root = (typeof exportRoot !== "undefined" && exportRoot)
		    ? exportRoot
		    : this;
		
		var _this = root;
		
		
		// =====================================================
		// KARAKTER
		// =====================================================
		
		var hero = _this.hero_mc || _this.btn_cowo;
		
		if (hero) {
		    hero.visible = true;
		}
		
		if (_this.btn_cewe) {
		    _this.btn_cewe.visible = false;
		}
		
		
		// =====================================================
		// FISIKA
		// =====================================================
		
		var speed = 6;
		var gravity = 1.5;
		var jumpPower = -16;
		
		var vy = 0;
		var isJumping = false;
		
		
		// =====================================================
		// CAMERA (Disesuaikan untuk Layar 800x480)
		// =====================================================
		
		var cameraX = 400; // Posisi player di tengah layar (800 / 2)
		var cameraSmooth = 0.15;
		var previousHeroX = hero ? hero.x : 400;
		
		
		// =====================================================
		// STATUS GAME
		// =====================================================
		
		if (window.hitCountMusuh === undefined) {
		    window.hitCountMusuh = 0;
		}
		
		if (window.isInvincibleMusuh === undefined) {
		    window.isInvincibleMusuh = false;
		}
		
		if (window.isKotakHilang === undefined) {
		    window.isKotakHilang = false;
		}
		
		if (window.isKotakLillaHilang === undefined) {
		    window.isKotakLillaHilang = false;
		}
		
		if (window.isMusuhKalah === undefined) {
		    window.isMusuhKalah = false;
		}
		
		
		// =====================================================
		// OBJEK SOAL
		// =====================================================
		
		var targetSoal1 =
		    _this.btn_soal1 ||
		    _this.kotak ||
		    _this.BATU2;
		
		var targetSoal2 =
		    _this.btn_soal2 ||
		    _this.kotak_ungu ||
		    _this.BATU3;
		
		
		// =====================================================
		// MUSUH
		// =====================================================
		
		var enemies = [
		    _this.enemy1,
		    _this.enemy2,
		    _this.btn_musuh
		].filter(Boolean);
		
		
		// =====================================================
		// HILANGKAN SOAL
		// =====================================================
		
		if (window.isKotakHilang) {
		
		    if (_this.btn_soal1)
		        _this.btn_soal1.visible = false;
		
		    if (_this.kotak)
		        _this.kotak.visible = false;
		
		    window.isMusuhKalah = true;
		}
		
		
		if (targetSoal2) {
		    targetSoal2.visible =
		        !window.isKotakLillaHilang;
		}
		
		
		// =====================================================
		// VISIBILITAS MUSUH (MENCEGAH MUSUH NYANGKUT DI POJOK KIRI)
		// =====================================================
		
		enemies.forEach(function(enemy) {
		    if (window.isMusuhKalah || !_this.BATU2) {
		        enemy.visible = false;
		    } else {
		        enemy.visible = true;
		    }
		});
		
		
		// =====================================================
		// UKURAN PLAYER
		// =====================================================
		
		var pBounds =
		    (hero && hero.getNominalBounds)
		    ? hero.getNominalBounds()
		    : (hero ? hero.getBounds() : null);
		
		var pHeight =
		    pBounds ? pBounds.height : 60;
		
		var pHalfHeight =
		    pHeight / 2;
		
		
		// =====================================================
		// LANTAI (Disesuaikan untuk tinggi 480)
		// =====================================================
		
		var permukaanLantaiY = 420;
		
		var groundY =
		    permukaanLantaiY - pHalfHeight;
		
		
		// =====================================================
		// PLATFORM & BACKGROUND YANG IKUT BERGESER
		// =====================================================
		var movingElements = [
		    _this.BATU1,
		    _this.BATU2,
		    _this.BATU3,
		    _this.btn_soal1,
		    _this.btn_soal2,
		    _this.kotak,
		    _this.kotak_ungu,
		    _this.finish,
		    _this.bg,
		    _this.background,
		    _this.enemy1,
		    _this.enemy2,
		    _this.btn_musuh
		].filter(Boolean);
		
		
		// =====================================================
		// POSISI MUSUH DI BATU 2
		// =====================================================
		
		enemies.forEach(function(enemy) {
		
		    if (
		        enemy &&
		        _this.BATU2 &&
		        !window.isMusuhKalah
		    ) {
		
		        var b2Bounds =
		            _this.BATU2.getNominalBounds
		            ? _this.BATU2.getNominalBounds()
		            : _this.BATU2.getBounds();
		
		        var b2Height =
		            b2Bounds
		            ? b2Bounds.height
		            : 30;
		
		        var mBounds =
		            enemy.getNominalBounds
		            ? enemy.getNominalBounds()
		            : enemy.getBounds();
		
		        var mHeight =
		            mBounds
		            ? mBounds.height
		            : 50;
		
		        enemy.y =
		            (_this.BATU2.y - b2Height / 2)
		            - mHeight / 2;
		
		        enemy.x =
		            _this.BATU2.x;
		    }
		
		});
		
		
		// =====================================================
		// POSISI AWAL PLAYER
		// =====================================================
		
		if (hero) {
		
		    if (
		        window.isKotakLillaHilang &&
		        targetSoal2
		    ) {
		
		        hero.x =
		            targetSoal2.x + 40;
		
		        hero.y =
		            groundY;
		
		        vy = 0;
		        isJumping = false;
		
		    }
		
		    else if (
		        window.isKotakHilang &&
		        targetSoal1
		    ) {
		
		        hero.x =
		            targetSoal1.x + 40;
		
		        hero.y =
		            groundY;
		
		        vy = 0;
		        isJumping = false;
		
		    }
		
		    else {
		
		        hero.x = 100;
		
		        hero.y =
		            groundY;
		
		        vy = 0;
		        isJumping = false;
		    }
		    
		    previousHeroX = hero.x;
		}
		
		
		// =====================================================
		// KEYBOARD
		// =====================================================
		
		var keys = {};
		
		window.addEventListener(
		    "keydown",
		    function(e) {
		        keys[e.keyCode] = true;
		    }
		);
		
		window.addEventListener(
		    "keyup",
		    function(e) {
		        keys[e.keyCode] = false;
		    }
		);
		
		
		// =====================================================
		// KONTROL HP
		// =====================================================
		
		var jalanKiri = false;
		var jalanKanan = false;
		var kecepatanLayar = 5;
		
		
		// =====================================================
		// TOMBOL KIRI
		// =====================================================
		
		if (_this.btn_kiri) {
		    _this.btn_kiri.removeAllEventListeners();
		    _this.btn_kiri.cursor = "pointer";
		    _this.btn_kiri.on("mousedown", function() { jalanKiri = true; });
		    _this.btn_kiri.on("pressup", function() { jalanKiri = false; });
		}
		
		
		// =====================================================
		// TOMBOL KANAN
		// =====================================================
		
		if (_this.btn_kanan) {
		    _this.btn_kanan.removeAllEventListeners();
		    _this.btn_kanan.cursor = "pointer";
		    _this.btn_kanan.on("mousedown", function() { jalanKanan = true; });
		    _this.btn_kanan.on("pressup", function() { jalanKanan = false; });
		}
		
		
		// =====================================================
		// TOMBOL LOMPAT
		// =====================================================
		
		if (_this.btn_atas) {
		    _this.btn_atas.removeAllEventListeners();
		    _this.btn_atas.cursor = "pointer";
		    _this.btn_atas.on("click", function() {
		        if (hero && !isJumping) {
		            vy = jumpPower;
		            isJumping = true;
		        }
		    });
		}
		
		
		// =====================================================
		// TOMBOL SERANG
		// =====================================================
		
		if (_this.btn_serang) {
		    _this.btn_serang.removeAllEventListeners();
		    _this.btn_serang.cursor = "pointer";
		    _this.btn_serang.on("click", function() {
		        if (hero && hero.gotoAndPlay) {
		            hero.gotoAndPlay("serang");
		        }
		    });
		}
		
		
		// =====================================================
		// GAME LOOP
		// =====================================================
		
		createjs.Ticker.removeEventListener("tick", updateGame);
		createjs.Ticker.addEventListener("tick", updateGame);
		
		
		// =====================================================
		// UPDATE GAME
		// =====================================================
		
		function updateGame() {
		
		    if (!hero) {
		        return;
		    }
		
		
		    // =================================================
		    // GERAK KIRI
		    // =================================================
		
		    if (
		        keys[37] ||
		        keys[65] ||
		        jalanKiri
		    ) {
		
		        var gerakKiri =
		            jalanKiri
		            ? kecepatanLayar
		            : speed;
		
		        hero.x -= gerakKiri;
		
		        hero.scaleX = -1;
		    }
		
		
		    // =================================================
		    // GERAK KANAN
		    // =================================================
		
		    if (
		        keys[39] ||
		        keys[68] ||
		        jalanKanan
		    ) {
		
		        var gerakKanan =
		            jalanKanan
		            ? kecepatanLayar
		            : speed;
		
		        hero.x += gerakKanan;
		
		        hero.scaleX = 1;
		    }
		
		
		    // =================================================
		    // LOMPAT
		    // =================================================
		
		    if (
		        (
		            keys[38] ||
		            keys[87] ||
		            keys[32]
		        ) &&
		        !isJumping
		    ) {
		
		        vy = jumpPower;
		
		        isJumping = true;
		    }
		
		
		    // =================================================
		    // GRAVITASI
		    // =================================================
		
		    vy += gravity;
		
		    hero.y += vy;
		
		
		    var kakiY =
		        hero.y + pHalfHeight;
		
		    var onAnyPlatform = false;
		
		
		    // =================================================
		    // DETEKSI PLATFORM
		    // =================================================
		
		    var platforms = [_this.BATU1, _this.BATU2, _this.BATU3];
		
		    for (
		        var i = 0;
		        i < platforms.length;
		        i++
		    ) {
		
		        var plat = platforms[i];
		
		        if (!plat) {
		            continue;
		        }
		
		        var platBounds =
		            plat.getNominalBounds
		            ? plat.getNominalBounds()
		            : plat.getBounds();
		
		        var platWidth =
		            platBounds
		            ? platBounds.width
		            : 80;
		
		        var platHeight =
		            platBounds
		            ? platBounds.height
		            : 30;
		
		        var platLeft =
		            plat.x - platWidth / 2;
		
		        var platRight =
		            plat.x + platWidth / 2;
		
		        var platTop =
		            plat.y - platHeight / 2;
		
		
		        if (
		            hero.x >= platLeft &&
		            hero.x <= platRight &&
		            vy >= 0
		        ) {
		
		            if (
		                kakiY >= platTop - 15 &&
		                (kakiY - vy) <= platTop + 25
		            ) {
		
		                hero.y =
		                    platTop - pHalfHeight;
		
		                vy = 0;
		
		                isJumping = false;
		
		                onAnyPlatform = true;
		
		                break;
		            }
		        }
		    }
		
		
		    // =================================================
		    // LANTAI
		    // =================================================
		
		    if (
		        !onAnyPlatform &&
		        hero.y >= groundY
		    ) {
		
		        hero.y = groundY;
		
		        vy = 0;
		
		        isJumping = false;
		    }
		
		
		    // =================================================
		    // CAMERA
		    // =================================================
		
		    var heroDelta = hero.x - previousHeroX;
		    
		    if (heroDelta !== 0) {
		        movingElements.forEach(function(el) {
		            if (el) {
		                el.x -= heroDelta;
		            }
		        });
		    }
		    
		    previousHeroX = hero.x;
		
		
		    // =================================================
		    // SOAL 1
		    // =================================================
		
		    if (
		        !window.isKotakHilang &&
		        targetSoal1
		    ) {
		
		        if (
		            Math.abs(hero.x - targetSoal1.x) < 50 &&
		            Math.abs(hero.y - targetSoal1.y) < 70
		        ) {
		
		            window.posisiSoal1X =
		                targetSoal1.x;
		
		            window.posisiSoal1Y =
		                targetSoal1.y;
		
		            cleanUpAndGo(13);
		
		            return;
		        }
		    }
		
		
		    // =================================================
		    // SOAL 2
		    // =================================================
		
		    if (
		        window.isKotakHilang &&
		        !window.isKotakLillaHilang &&
		        targetSoal2
		    ) {
		
		        if (
		            Math.abs(hero.x - targetSoal2.x) < 50 &&
		            Math.abs(hero.y - targetSoal2.y) < 70
		        ) {
		
		            window.posisiSoal2X =
		                targetSoal2.x;
		
		            window.posisiSoal2Y =
		                targetSoal2.y;
		
		            cleanUpAndGo(14);
		
		            return;
		        }
		    }
		
		
		    // =================================================
		    // FINISH
		    // =================================================
		
		    if (
		        _this.finish &&
		        window.isKotakHilang &&
		        window.isKotakLillaHilang
		    ) {
		
		        if (
		            Math.abs(hero.x - _this.finish.x) < 50 &&
		            Math.abs(hero.y - _this.finish.y) < 70
		        ) {
		
		            cleanUpAndGo(16, true);
		
		            return;
		        }
		    }
		}
		
		
		// =====================================================
		// PINDAH FRAME
		// =====================================================
		
		function cleanUpAndGo(
		    frameIndex,
		    isStop
		) {
		
		    var targetRoot =
		        (typeof exportRoot !== "undefined" && exportRoot)
		        ? exportRoot
		        : _this;
		
		
		    createjs.Ticker.removeEventListener(
		        "tick",
		        updateGame
		    );
		
		
		    if (isStop) {
		
		        targetRoot.gotoAndStop(
		            frameIndex
		        );
		
		    } else {
		
		        targetRoot.gotoAndPlay(
		            frameIndex
		        );
		    }
		}
	}
